import { useState, useEffect, useContext } from "react";
import { CartContext } from "../context/CartContext";
import { FaTrash, FaPlus, FaMinus, FaShoppingCart } from "react-icons/fa";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import api from '../api/client'; 

function CartCarrito({ idCarrito, onClose }) {
  const { removeFromCart, increaseQuantity, decreaseQuantity } = useContext(CartContext);
  const [user, setUser] = useState(null);
  const [dbCart, setDbCart] = useState([]);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  // 🔹 Cargar usuario del localStorage
  useEffect(() => {
    const storedUser = localStorage.getItem("user");
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  // 🔹 Cargar carrito desde backend
  useEffect(() => {
    if (user?.iduser) {
      fetchCart();
    }
  }, [user?.iduser]);

  const fetchCart = async () => {
    try {
      setLoading(true);
      const response = await api.get(`api/carrito/${user.iduser}`);

      const transformedCart = response.data.map(item => ({
        id: item.idproducto,
        idcarrito: item.id_carrito || item.id, 
        name: item.producto?.nombre || 'Producto no disponible',
        price: item.producto?.precio || 0,
        quantity: item.cantidad,
        foto: item.producto?.foto || null
      }));

      setDbCart(transformedCart);
    } catch (error) {
      console.error("Error al obtener carrito", error);
      toast.error("Error al cargar el carrito");
    } finally {
      setLoading(false);
    }
  };

  // 🔹 Eliminar producto
  const handleRemoveFromCart = async (productId) => {
    const item = dbCart.find(i => i.id === productId);

    try {
      setLoading(true);
      await api.post("api/carrito/operar", {
        operacion: "Eliminar",
        iduser: user?.iduser,
        idproducto: productId,
        id_carrito: idCarrito
      });

      removeFromCart(productId);
      setDbCart(prev => prev.filter(item => item.id !== productId));

      toast.success("Producto eliminado del carrito");
    } catch (error) {
      console.error("Error al eliminar del carrito", error);

      if (error.response?.data?.error === "Producto no encontrado en el carrito") {
        setDbCart(prev => prev.filter(item => item.id !== productId));
      }

      toast.error(error.response?.data?.error || "Error al eliminar producto");
    } finally {
      setLoading(false);
    }
  };

  // 🔹 Aumentar cantidad
  const handleIncreaseQuantity = async (productId) => {
    const item = dbCart.find(i => i.id === productId);

    try {
      setLoading(true);
      await api.post("api/carrito/operar", {
        operacion: "Agregar",
        iduser: user?.iduser,
        idproducto: productId,
        id_carrito: idCarrito,
        cantidad: 1,
        precio_unitario: item.price
      });

      increaseQuantity(productId);

      setDbCart(prev => prev.map(itm =>
        itm.id === productId ? { ...itm, quantity: itm.quantity + 1 } : itm
      ));

    } catch (error) {
      console.error("Error al aumentar cantidad", error);
      toast.error("Error al actualizar cantidad");
    } finally {
      setLoading(false);
    }
  };

  // 🔹 Disminuir cantidad
  const handleDecreaseQuantity = async (productId) => {
    const item = dbCart.find(i => i.id === productId);

    if (!item || item.quantity <= 1) return;

    try {
      setLoading(true);
      await api.post("api/carrito/operar", {
        operacion: "Actualizar",
        iduser: user?.iduser,
        idproducto: productId,
        id_carrito: idCarrito,
        cantidad: item.quantity - 1,
        precio_unitario: item.price
      });

      decreaseQuantity(productId);

      setDbCart(prev => prev.map(itm =>
        itm.id === productId ? { ...itm, quantity: itm.quantity - 1 } : itm
      ));

    } catch (error) {
      console.error("Error al disminuir cantidad", error);
      toast.error("Error al actualizar cantidad");
    } finally {
      setLoading(false);
    }
  };

  // 🔹 Ir al pago
  const handleGoToPayment = () => {
    if (dbCart.length === 0) {
      toast.error("El carrito está vacío.");
      return;
    }

    const totalAmount = calculateTotal();

    navigate("/pagoCarrito", { state: { cart: dbCart, total: totalAmount, id_carrito: idCarrito } });
  };

  const calculateTotal = () => {
    return dbCart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  };

  return (
    <div className="main-content">
      <h2 className="text-center">
        <FaShoppingCart /> Carrito de Compras
      </h2>

      {loading && <div className="text-center my-3">Cargando...</div>}

      <ul>
        {dbCart.length > 0 ? (
          dbCart.map((item) => (
            <li key={item.id} className="list-group-item d-flex justify-content-between align-items-center">

              <div className="d-flex align-items-center">
                {item.foto && (
                  <img
                    src={`  /api/productos/foto/${item.foto}`}
                    alt=""
                    style={{
                      width: '50px',
                      height: '50px',
                      objectFit: 'cover',
                      marginRight: '15px',
                      borderRadius: '5px'
                    }}
                  />
                )}

                <div>
                  <h6 className="mb-0">{item.name}</h6>
                  <small>
                    ${item.price} x {item.quantity} = ${(item.price * item.quantity).toFixed(2)}
                  </small>
                </div>
              </div>

              <div>
                <button
                  className="btn btn-outline-primary btn-sm me-2"
                  onClick={() => handleIncreaseQuantity(item.id)}
                  disabled={loading}
                >
                  <FaPlus />
                </button>

                <button
                  className="btn btn-outline-secondary btn-sm me-2"
                  onClick={() => handleDecreaseQuantity(item.id)}
                  disabled={loading || item.quantity <= 1}
                >
                  <FaMinus />
                </button>

                <button
                  className="btn btn-danger btn-sm"
                  onClick={() => handleRemoveFromCart(item.id)}
                  disabled={loading}
                >
                  <FaTrash />
                </button>
              </div>

            </li>
          ))
        ) : (
          <p className="text-center text-muted my-3">Tu carrito está vacío</p>
        )}
      </ul>

      <h3 className="mt-3 text-light">Total: ${calculateTotal().toFixed(2)}</h3>

      <div className="d-flex gap-2 mt-3">
        <button
          className="btn btn-success btn-lg flex-grow-1"
          onClick={handleGoToPayment}
          disabled={loading || dbCart.length === 0}
        >
          {loading ? 'Procesando...' : (<><FaShoppingCart /> Finalizar Compra</>)}
        </button>
      </div>
    </div>
  );
}

export default CartCarrito;
